mapper.select:
SELECT t2.`name` AS logistic_name, t3.`name` AS brand_name, t1.id, t1.short_name, t1.name, t1.contact_name, t1.address, t1.province, t1.city, t1.district, t1.delivery_address, t1.mobile, t1.mobile2, t1.logistic_id, t1.brand_id, t1.balance, t1.note, t1.create_time, t1.update_time, t1.creator, t1.updater FROM zc_customer t1 LEFT JOIN zc_logistics t2 ON t1.logistic_id = t2.id AND t2.deleted = 0 LEFT JOIN zc_brand t3 ON t1.brand_id = t3.id AND t3.deleted = 0 WHERE t1.deleted = 0
AND t1.short_name LIKE CONCAT('%', #{reqVO.shortName}, '%')
AND t1.name LIKE CONCAT('%', #{reqVO.name}, '%')
AND t1.logistic_id = #{reqVO.logisticId}
AND t1.brand_id = #{reqVO.brandId}
ORDER BY t1.id DESC
